INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'la-drama-comedia-de-la-historia-atroz', 'La Drama-Comedia de la Historia Atroz', 'Dinámica de narración improvisada y representación cómica donde las patrullas actúan pasajes absurdos y exagerados relatados por el animador.', '<h2>📜 Descripción de La Drama-Comedia de la Historia Atroz</h2>
<p><b>La Drama-Comedia de la Historia Atroz</b> es una dinámica scout de desinhibición escénica, creatividad teatral y expresión oral colectiva. Los participantes se organizan por patrullas o seisenas en el salón de fogata o anfiteatro de campamento. El animador o guía comienza a relatar una historia improvisada llena de situaciones dramáticas, insólitas y cómicas (ej. <i>''Un cruce tempestuoso en la selva interrumpido por mosquitos gigantes''</i>). A medida que el relator nombra a los personajes y acciones, los scouts deben saltar al escenario a representar físicamente los acontecimientos con gestos exagerados y sonidos de comedia sin interrupción.</p>
<p>Esta actividad estimula la soltura teatral, la pérdida del miedo al ridículo y el trabajo colaborativo en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega La Drama-Comedia de la Historia Atroz?</h2>
<p>Para llevar a cabo la dinámica con dinamismo y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Formación del Escenario:</b> Se ubica a las seisenas en semicírculo frente al área de actuación o fogata.</li>
  <li><b>Inicio del Relato:</b> El dirigente inicia la narración oral marcando giros inesperados y divertidos.</li>
  <li><b>Entrada en Escena:</b> Tan pronto como el animador menciona un elemento o personaje (ej. <i>''El árbol centenario que temblaba de frío''</i>), uno o más scouts corren al centro a personificarlo físicamente.</li>
  <li><b>Improvisación Síncrona:</b> Los actores adaptan sus gestos y diálogos en tiempo real según el ritmo vertiginoso del relato.</li>
  <li><b>Cierre con Ovación:</b> La historia concluye con una escena grupal disparatada y el aplauso Scout de la unidad.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de La Drama-Comedia de la Historia Atroz</h2>
<p>La actividad valora la creatividad y la soltura cómica en el Tally:</p>
<ul>
  <li><b>Mayor Expresividad Dramática:</b> Otorgar 5 puntos a la patrulla cuyos integrantes encarnen las acciones con mayor entusiasmo y gesticulación.</li>
  <li><b>Rapidez de Reacción Escénica:</b> Otorgar 3 puntos al equipo que salga al centro al instante de ser nombrado en el cuento.</li>
  <li><b>Risa Colectiva:</b> Otorgar 3 puntos a la representación que desate la mayor alegría en la Manada o Unidad.</li>
</ul>', '/uploads/la-drama-comedia-de-la-historia-atroz.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Ninguno"], "objetivos": ["Estimular la creatividad", "Fomentar la comunicación e interpretación", "Trabajo en equipo", "Crear un ambiente de distensión"], "justificacion_areas": "La Drama-Comedia de la Historia Atroz potencia la creatividad al exigir la improvisación inmediata de roles dramáticos, gestos cómicos y expresión corporal. Desarrolla la sociabilidad al afianzar la desinhibición social, el juego cooperativo sin juicio y el espíritu festivo en la unidad.", "variaciones": "<b>Historia Atroz con Efectos de Sonido:</b> Una patrulla actúa mientras otra realiza la banda sonora y ruidos ambientales en vivo.<br><b>Historia Atroz en Reversa:</b> Representar la trama comenzando por el desenlace dramático hasta llegar al inicio cómico.<br><b>Edición Leyendas Nua Mana:</b> Recrear pasajes humorísticos basados en anécdotas reales del Grupo Scout.", "recomendaciones": "Mantener un ritmo fluido en la narración sin pausas prolongadas. Promover un ambiente festivo donde se valore la audacia escénica.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando el desarrollo del relato para intervenir en el momento exacto con expresiones teatrales."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Improvisando personajes cómicos e insólitos frente a los compañeros."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando creatividad oral y gestual en la caracterización de la escena."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Adaptando las reacciones escénicas según los giros del argumento narrado."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Demostrando soltura expresiva e iniciativa artística en la Tropa."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando elementos dramáticos para potenciar el humor en la patrulla."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Acatando los roles asignados en el relato sin vacilaciones."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Participando con alegría y respeto en las representaciones grupales."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Construyendo un clima libre de burlas que incentive la participación de todas."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Apoyando con aplausos el desempeño escénico de las compañeras de unidad."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando el compañerismo y la confianza mutua en presentaciones de fogata."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión e integración entre las distintas patrullas."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

